mapper.select:
SELECT d.*, dept.name as dept_name FROM doctor d LEFT JOIN department dept ON d.dept_id = dept.id WHERE d.deleted = 0 AND dept.deleted = 0
AND (d.name LIKE CONCAT('%', #{keyword}, '%') OR d.title LIKE CONCAT('%', #{keyword}, '%'))
AND d.dept_id = #{deptId}
AND d.status = #{status}
ORDER BY d.create_time DESC
